vector<string> readLineTokens(istream& in) {
    string line;
    getline(in, line);
    stringstream ss(line);
    vector<string> tokens;
    string token;
    while (ss >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

vector<int> readLineNumbers(istream& in) {
    vector<string> tokens = readLineTokens(in);
    vector<int> nums(tokens.size());
    for (size_t i = 0; i < tokens.size(); i++) {
        nums[i] = stoi(tokens[i]);
    }
    return nums;
}

vector<char> replaceXWithCharInArray(const vector<char>& array, int size, char ch) {
    vector<char> newArray(size);
    for (int i = 0; i < size; i++) {
        newArray[i] = (array[i] == 'X') ? ch : array[i];
    }
    return newArray;
}

long long computeNumberOfWays(const vector<char>& str, int n);

long long matchPattern(const vector<char>& str, const string& suffix, int n, int un) {
    if (n < 2) return 0;
    char lastChar = suffix[1];
    char firstChar = suffix[0];
    if (str[n - 1] == '_' || str[n - 1] == lastChar) {
        if (str[n - 2] == '_' || str[n - 2] == firstChar) {
            return (long long)pow(10, un);
        }
    }
    return 0;
}

long long computeNumberOfWays(const vector<char>& str, int n) {
    if (n == 1 || str[0] == '0') return 0;
